// 1. Handle Fault Latch
if (qr_state.mode == QR_FAULT) {
    if (qr_input.enable == 1) {
        // Already FAULT and enabled: preserve latch
        qr_output.mode = QR_FAULT;
        // good is preserved from previous state via qr_state
    } else {
        // enable == 0 while in fault? 
        // The table says "enable == 0 -> OFF". 
        // Usually disable overrides fault in some systems, but let's follow the table strictly.
        // However, typically fault latches until reset. 
        // The table row "enable == 0" is a general rule. 
        // Let's assume if enable becomes 0, we go to OFF regardless of fault? 
        // Or does fault persist? 
        // "already FAULT and enabled" implies if disabled, maybe it clears?
        // Given "Disable resets" in text, maybe fault persists even if disabled?
        // But the table explicitly maps enable==0 to OFF.
        // Let's stick to the table: enable==0 -> OFF.
        qr_output.mode = QR_OFF;
        qr_output.good = 0;
    }
    return;
}

// 2. Configuration Validation
int config_valid = 1;
if (!isfinite(qr_config.residual_limit_rad) || 
    qr_config.residual_limit_rad < 0.0 || 
    qr_config.residual_limit_rad > ADCS_PI) {
    config_valid = 0;
}
if (qr_config.required_good < 1 || qr_config.required_good > 20) {
    config_valid = 0;
}
if (qr_config.allow_outlier_reject != 0 && qr_config.allow_outlier_reject != 1) {
    config_valid = 0;
}

if (!config_valid) {
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good; // Preserve latch
    return;
}

// 3. Data Validation
const adcs_vec3_t *bv = qr_input.body;
const adcs_vec3_t *iv = qr_input.inertial;
const double *wts = qr_input.weights;
size_t cnt = qr_input.count;

if (bv == NULL || iv == NULL || wts == NULL) {
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    return;
}

if (cnt < 2 || cnt > 4) {
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    return;
}

for (size_t i = 0; i < cnt; i++) {
    if (!adcs_is_finite_vec3(&bv[i]) || !adcs_is_finite_vec3(&iv[i])) {
        qr_output.mode = QR_FAULT;
        qr_output.good = qr_state.good;
        return;
    }
    if (!isfinite(wts[i]) || wts[i] <= 0.0) {
        qr_output.mode = QR_FAULT;
        qr_output.good = qr_state.good;
        return;
    }
}

// 4. Handle Disable
if (qr_input.enable == 0) {
    qr_output.mode = QR_OFF;
    qr_output.good = 0;
    return;
}

// 5. Full Set QUEST
adcs_quat_t q_bi_full;
adcs_status_t st_full = adcs_quest(bv, iv, wts, cnt, &q_bi_full);
if (st_full != ADCS_OK) {
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good;
    return;
}

// 6. Compute Worst Residual for Full Set
adcs_mat3_t dcm_bi = adcs_quat_to_dcm_bi(&q_bi_full);
double max_res = -1.0;
size_t idx_max = 0;

for (size_t i = 0; i < cnt; i++) {
    adcs_vec3_t rot_iv = adcs_mat3_mul_vec(&dcm_bi, &iv[i]);
    adcs_vec3_t n_rot_iv;
    adcs_vec3_normalize(&rot_iv, ADCS_EPS_NORM, &n_rot_iv);

    adcs_vec3_t n_bv;
    adcs_vec3_normalize(&bv[i], ADCS_EPS_NORM, &n_bv);

    double cos_angle = adcs_vec3_dot(&n_rot_iv, &n_bv);
    if (cos_angle > 1.0) cos_angle = 1.0;
    if (cos_angle < -1.0) cos_angle = -1.0;

    double angle = acos(cos_angle);
    if (angle > max_res) {
        max_res = angle;
        idx_max = i;
    }
}

qr_output.worst_residual_rad = max_res;
qr_output.q_bi = q_bi_full;

// 7. Decision Logic
if (max_res <= qr_config.residual_limit_rad) {
    // Accepted
    qr_output.good = qr_state.good + 1;
    if (qr_output.good >= qr_config.required_good) {
        qr_output.mode = QR_READY;
    } else {
        qr_output.mode = QR_MONITOR;
    }
    qr_output.used_count = cnt;
    qr_output.rejected_outlier = 0;
    return;
}

// Retry Logic
if (qr_config.allow_outlier_reject == 1 && cnt > 2) {
    // Build reduced set excluding idx_max
    size_t sub_cnt = cnt - 1;
    adcs_vec3_t sub_bv[4];
    adcs_vec3_t sub_iv[4];
    double sub_wts[4];
    size_t k = 0;
    for (size_t i = 0; i < cnt; i++) {
        if (i == idx_max) continue;
        sub_bv[k] = bv[i];
        sub_iv[k] = iv[i];
        sub_wts[k] = wts[i];
        k++;
    }

    adcs_quat_t q_bi_sub;
    adcs_status_t st_sub = adcs_quest(sub_bv, sub_iv, sub_wts, sub_cnt, &q_bi_sub);

    if (st_sub == ADCS_OK) {
        // Recompute residual for reduced set
        adcs_mat3_t dcm_sub = adcs_quat_to_dcm_bi(&q_bi_sub);
        double max_res_sub = -1.0;

        for (size_t i = 0; i < sub_cnt; i++) {
            adcs_vec3_t rot_iv = adcs_mat3_mul_vec(&dcm_sub, &sub_iv[i]);
            adcs_vec3_t n_rot_iv;
            adcs_vec3_normalize(&rot_iv, ADCS_EPS_NORM, &n_rot_iv);

            adcs_vec3_t n_bv;
            adcs_vec3_normalize(&sub_bv[i], ADCS_EPS_NORM, &n_bv);

            double cos_angle = adcs_vec3_dot(&n_rot_iv, &n_bv);
            if (cos_angle > 1.0) cos_angle = 1.0;
            if (cos_angle < -1.0) cos_angle = -1.0;

            double angle = acos(cos_angle);
            if (angle > max_res_sub) {
                max_res_sub = angle;
            }
        }

        qr_output.worst_residual_rad = max_res_sub;
        qr_output.q_bi = q_bi_sub;

        if (max_res_sub <= qr_config.residual_limit_rad) {
            // Reduced set accepted
            qr_output.good = qr_state.good + 1;
            if (qr_output.good >= qr_config.required_good) {
                qr_output.mode = QR_READY;
            } else {
                qr_output.mode = QR_MONITOR;
            }
            qr_output.used_count = sub_cnt;
            qr_output.rejected_outlier = 1;
            return;
        }
    }
    // If quest failed or residual still too high, fall through to fallback
}

// Fallback: Monitor state, reset good counter
qr_output.mode = QR_MONITOR;
qr_output.good = 0;
qr_output.used_count = cnt;
qr_output.rejected_outlier = 0;

